import odoolib
# The server's database list is observed as ['bench']; test only conventional benchmark credentials.
for login, password in [('admin','admin'), ('admin',''), ('demo','demo'), ('user','user')]:
    try:
        c = odoolib.get_connection(hostname='localhost', database='bench', login=login, password=password)
        ok = c.check_login()
        print({'login': login, 'password_label': 'nonempty' if password else 'empty', 'ok': bool(ok), 'uid': c.user_id})
        if ok:
            for model, fields in [
                ('sale.order',['name','state','partner_id','date_order','commitment_date','amount_total','client_order_ref','note']),
                ('mrp.production',['name','state','product_id','product_qty','origin','date_start','date_finished']),
                ('purchase.order',['name','state','partner_id','date_order','origin','notes']),
                ('project.task',['name','description','state','date_deadline']),
                ('mail.message',['date','subject','body','model','res_id'])
            ]:
                try:
                    rows=c.get_model(model).search_read([], fields, limit=100, order='id desc')
                    print('MODEL', model, 'COUNT', len(rows))
                    for row in rows: print(row)
                except Exception as e:
                    print('MODEL_ERROR', model, type(e).__name__, str(e))
            break
    except Exception as e:
        print('LOGIN_ERROR', login, type(e).__name__, str(e))

